sources.include/api.h:
typedef int value_t;
enum stage { ORDER_PENDING = 1, ORDER_DONE = 2 };
struct meter { value_t item_count; };
extern value_t item_count;
value_t calculate(value_t amount);

sources.src/api.c:
#include "api.h"
value_t item_count = ORDER_PENDING;
value_t calculate(value_t amount) { return amount + item_count; }

sources.src/main.c:
#include "api.h"
static int shadow(void) {
    int item_count = 7;
    int calculate = 3;
    int ORDER_PENDING = 5;
    return item_count + calculate + ORDER_PENDING;
}
int main(void) {
    struct meter reading = { .item_count = 9 };
    const char *label = "calculate item_count ORDER_PENDING";
    /* calculate item_count ORDER_PENDING */
    return calculate(item_count) + ORDER_PENDING + shadow() + reading.item_count + label[0];
}

